CREATE TABLE members (
    id         bigint PRIMARY KEY,
    email      text,
    status     text,
    last_login timestamptz,
    memo       text
);

CREATE UNIQUE INDEX ON members (lower(email));
CREATE INDEX ON members (id) WHERE status = 'active';

-- update가 잦은 테이블의 HOT 비율을 올리려고 적용
ALTER TABLE members SET (fillfactor = 80);
VACUUM members;

-- 데이터베이스 로케일은 ko_KR.UTF-8입니다.
CREATE INDEX idx_users_email ON users (email);
ANALYZE users;

EXPLAIN SELECT * FROM users WHERE email LIKE 'kim%';
--                          QUERY PLAN
-- ----------------------------------------------------------
--  Seq Scan on users  (cost=0.00..24531.00 rows=98 width=64)
--    Filter: (email ~~ 'kim%'::text)

CREATE INDEX users_name_trgm ON users USING gin (name gin_trgm_ops);

-- (A) 인덱스를 탑니다
SELECT * FROM users WHERE name LIKE '%kim%';

-- (B) 200만 행을 전부 읽고 정렬합니다
SELECT name FROM users ORDER BY name <-> 'kim' LIMIT 10;

CREATE INDEX events_tags_gin ON events USING gin (tags jsonb_path_ops);

-- 이 조건은 인덱스를 탑니다
EXPLAIN SELECT * FROM events WHERE tags @> '["urgent"]';
--  Bitmap Heap Scan on events
--    Recheck Cond: (tags @> '["urgent"]'::jsonb)
--    ->  Bitmap Index Scan on events_tags_gin

-- 이 조건만 Seq Scan입니다
EXPLAIN SELECT * FROM events WHERE tags ? 'urgent';
--  Seq Scan on events
--    Filter: (tags ? 'urgent'::text)

VACUUM bloat_demo;

SELECT dead_tuple_count, dead_tuple_percent FROM pgstattuple('bloat_demo');
--  dead_tuple_count | dead_tuple_percent
-- ------------------+--------------------
--                 0 |                  0

SELECT pg_size_pretty(pg_relation_size('bloat_demo'));
--  pg_size_pretty
-- ----------------
--  13 MB

-- accounts에는 id=1, balance=1000 한 행이 있습니다.

-- Session A                       -- Session B
BEGIN;                             BEGIN;
UPDATE accounts                    -- 아래 문장은 A가 끝날 때까지 대기합니다
   SET balance = balance - 100     UPDATE accounts
 WHERE id = 1;                        SET balance = balance + 500
                                    WHERE id = 1;
COMMIT;

-- 계좌 이체 로직입니다. 하루에 몇 건씩 deadlock detected가 찍힙니다.

BEGIN;
UPDATE accounts SET balance = balance - :amt WHERE id = :from_id;
UPDATE accounts SET balance = balance + :amt WHERE id = :to_id;
COMMIT;

ALTER SYSTEM SET shared_buffers = '8GB';
ALTER SYSTEM SET work_mem = '32MB';
ALTER SYSTEM SET autovacuum_vacuum_cost_limit = 600;
SELECT pg_reload_conf();

SELECT name, setting, unit, pending_restart FROM pg_settings
WHERE name IN ('shared_buffers','work_mem','autovacuum_vacuum_cost_limit');
--             name             | setting | unit | pending_restart
-- ------------------------------+---------+------+-----------------
--  autovacuum_vacuum_cost_limit | 600     |      | f
--  shared_buffers               | 16384   | 8kB  | t
--  work_mem                     | 32768   | kB   | f
